tool_input.command:
cat >> test/invoice.test.mjs <<'EOF'

test("given fractional-cent lines, when totalled, then rounds only the final sum", () => {
  assert.equal(totalCents([0.4, 0.4]), 1);
});

test("given no lines, when totalled, then the total is 0", () => {
  assert.equal(totalCents([]), 0);
});
EOF
npm test 2>&1 | grep -E "^# (pass|fail)"
sed -i 's|amounts.reduce((total, amount) => Math.round(total + amount), 0)|Math.round(amounts.reduce((total, amount) => total + amount, 0))|' src/invoice.mjs
npm test 2>&1 | grep -E "^# (pass|fail)"; cat src/invoice.mjs
